import{_ as p,a0 as d,w as o,s as r,ao as l,I as i,x as s,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 上安裝 NetData 性能監控工具 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安裝 NetData 性能監控工具 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安裝 NetData 性能監控工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安裝 NetData 性能監控工具 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190706 Install NetData Performance Monitoring Tool On Linux","title":"在 Linux 上安裝 NetData 性能監控工具","tag":"201908","desc":""},"relativePath":"201908/20190706 Install NetData Performance Monitoring Tool On Linux.md","filePath":"[post].md"}'),h={name:"201908/20190706 Install NetData Performance Monitoring Tool On Linux.md"};function c(u,a,g,b,k,f){const n=d("Link");return o(),r("div",null,[a[23]||(a[23]=l('<h1 id="在-linux-上安裝-netdata-性能監控工具" tabindex="-1">在 Linux 上安裝 NetData 性能監控工具 <a class="header-anchor" href="#在-linux-上安裝-netdata-性能監控工具" aria-label="Permalink to “在 Linux 上安裝 NetData 性能監控工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/06/Install-netdata-720x340.png" alt=""></p><p><strong>NetData</strong> 是一個用於系統和應用的分佈式實時性能和健康監控工具。它提供了對系統中實時發生的所有事情的全面檢測。你可以在高度互動的 Web 儀表板中查看結果。使用 Netdata，你可以清楚地瞭解現在發生的事情，以及之前系統和應用中發生的事情。你無需成為專家即可在 Linux 系統中部署此工具。NetData 開箱即用，零配置、零依賴。只需安裝它然後坐等，之後 NetData 將負責其餘部分。</p><p>它有自己的內置 Web 服務器，以圖形形式顯示結果。NetData 非常快速高效，安裝後可立即開始分析系統性能。它是用 C 編程語言編寫的，所以它非常輕量。它佔用的單核 CPU 使用率不到 3％，內存佔用 10-15MB。我們可以輕鬆地在任何現有網頁上嵌入圖表，並且它還有一個插件 API，以便你可以監控任何應用。</p><p>以下是 Linux 系統中 NetData 的監控列表。</p><ul><li>CPU 使用率</li><li>RAM 使用率</li><li>交換內存使用率</li><li>內核內存使用率</li><li>硬盤及其使用率</li><li>網絡接口</li><li>IPtables</li><li>Netfilter</li><li>DDoS 保護</li><li>進程</li><li>應用</li><li>NFS 服務器</li><li>Web 服務器 （Apache 和 Nginx）</li><li>資料庫服務器 （MySQL），</li><li>DHCP 服務器</li><li>DNS 服務器</li><li>電子郵件服務</li><li>代理服務器</li><li>Tomcat</li><li>PHP</li><li>SNP 設備</li><li>等等</li></ul><p>NetData 是自由開源工具，它支持 Linux、FreeBSD 和 Mac OS。</p><h3 id="在-linux-上安裝-netdata" tabindex="-1">在 Linux 上安裝 NetData <a class="header-anchor" href="#在-linux-上安裝-netdata" aria-label="Permalink to “在 Linux 上安裝 NetData”">​</a></h3><p>Netdata 可以安裝在任何安裝了 Bash 的 Linux 發行版上。</p><p>最簡單的安裝 Netdata 的方法是從終端運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bash &lt;(curl -Ss https://my-netdata.io/kickstart-static64.sh)</span></span></code></pre></div><p>這將下載並安裝啓動和運行 Netdata 所需的一切。</p><p>有些用户可能不想在沒有研究的情況下將某些東西直接注入到 Bash。如果你不喜歡此方法，可以按照以下步驟在系統上安裝它。</p><h4 id="在-arch-linux-上" tabindex="-1">在 Arch Linux 上 <a class="header-anchor" href="#在-arch-linux-上" aria-label="Permalink to “在 Arch Linux 上”">​</a></h4>',14)),i("p",null,[a[1]||(a[1]=s("Arch Linux 默認倉庫中提供了最新版本。所以，我們可以使用以下 ",-1)),e(n,{href:"https://www.ostechnix.com/getting-started-pacman/"},{default:t(()=>[...a[0]||(a[0]=[s("pacman",-1)])]),_:1}),a[2]||(a[2]=s(" 命令安裝它：",-1))]),a[24]||(a[24]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S netdata</span></span></code></pre></div><h4 id="在基於-deb-和基於-rpm-的系統上" tabindex="-1">在基於 DEB 和基於 RPM 的系統上 <a class="header-anchor" href="#在基於-deb-和基於-rpm-的系統上" aria-label="Permalink to “在基於 DEB 和基於 RPM 的系統上”">​</a></h4><p>在基於 DEB （Ubuntu / Debian）或基於 RPM（RHEL / CentOS / Fedora） 系統的默認倉庫沒有 NetData。我們需要從它的 Git 倉庫手動安裝 NetData。</p><p>首先安裝所需的依賴項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Debian / Ubuntu</span></span>
<span class="line"><span>$ sudo apt-get install zlib1g-dev uuid-dev libuv1-dev liblz4-dev libjudy-dev libssl-dev libmnl-dev gcc make git autoconf autoconf-archive autogen automake pkg-config curl</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Fedora</span></span>
<span class="line"><span>$ sudo dnf install zlib-devel libuuid-devel libuv-devel lz4-devel Judy-devel openssl-devel libmnl-devel gcc make git autoconf autoconf-archive autogen automake pkgconfig curl findutils</span></span>
<span class="line"><span></span></span>
<span class="line"><span># CentOS / Red Hat Enterprise Linux</span></span>
<span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install autoconf automake curl gcc git libmnl-devel libuuid-devel openssl-devel libuv-devel lz4-devel Judy-devel lm_sensors make MySQL-python nc pkgconfig python python-psycopg2 PyYAML zlib-devel</span></span>
<span class="line"><span></span></span>
<span class="line"><span># openSUSE</span></span>
<span class="line"><span>$ sudo zypper install zlib-devel libuuid-devel libuv-devel liblz4-devel judy-devel openssl-devel libmnl-devel gcc make git autoconf autoconf-archive autogen automake pkgconfig curl findutils</span></span></code></pre></div><p>安裝依賴項後，在基於 DEB 或基於 RPM 的系統上安裝 NetData，如下所示。</p><p>Git 克隆 NetData 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/netdata/netdata.git --depth=100</span></span></code></pre></div><p>上面的命令將在當前工作目錄中創建一個名為 <code>netdata</code> 的目錄。</p><p>切換到 <code>netdata</code> 目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd netdata/</span></span></code></pre></div><p>最後，使用命令安裝並啓動 NetData：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ./netdata-installer.sh</span></span></code></pre></div><p><strong>示例輸出：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Welcome to netdata!</span></span>
<span class="line"><span>Nice to see you are giving it a try!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are about to build and install netdata to your system.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>It will be installed at these locations:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- the daemon at /usr/sbin/netdata</span></span>
<span class="line"><span> - config files at /etc/netdata</span></span>
<span class="line"><span> - web files at /usr/share/netdata</span></span>
<span class="line"><span> - plugins at /usr/libexec/netdata</span></span>
<span class="line"><span> - cache files at /var/cache/netdata</span></span>
<span class="line"><span> - db files at /var/lib/netdata</span></span>
<span class="line"><span> - log files at /var/log/netdata</span></span>
<span class="line"><span> - pid file at /var/run</span></span>
<span class="line"><span></span></span>
<span class="line"><span>This installer allows you to change the installation path.</span></span>
<span class="line"><span>Press Control-C and run the same command with --help for help.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Press ENTER to build and install netdata to your system &gt; ## Press ENTER key</span></span></code></pre></div><p>安裝完成後，你將在最後看到以下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-------------------------------------------------------------------------------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OK. NetData is installed and it is running (listening to *:19999).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-------------------------------------------------------------------------------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>INFO: Command line options changed. -pidfile, -nd and -ch are deprecated.</span></span>
<span class="line"><span>If you use custom startup scripts, please run netdata -h to see the</span></span>
<span class="line"><span>corresponding options and update your scripts.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hit http://localhost:19999/ from your browser.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To stop netdata, just kill it, with:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>killall netdata</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To start it, just run it:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/usr/sbin/netdata</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enjoy!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Uninstall script generated: ./netdata-uninstaller.sh</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/06/Deepin-Terminal_002-6.png" alt=""></p><p><em>安裝 NetData</em></p><p>NetData 已安裝並啓動。</p>`,20)),i("p",null,[a[4]||(a[4]=s("要在其他 Linux 發行版上安裝 Netdata，請參閲",-1)),e(n,{href:"https://docs.netdata.cloud/packaging/installer/"},{default:t(()=>[...a[3]||(a[3]=[s("官方安裝説明頁面",-1)])]),_:1}),a[5]||(a[5]=s("。",-1))]),a[25]||(a[25]=l(`<h3 id="在防火牆或者路由器上允許-netdata-的默認端口" tabindex="-1">在防火牆或者路由器上允許 NetData 的默認端口 <a class="header-anchor" href="#在防火牆或者路由器上允許-netdata-的默認端口" aria-label="Permalink to “在防火牆或者路由器上允許 NetData 的默認端口”">​</a></h3><p>如果你的系統在防火牆或者路由器後面，那麼必須允許默認端口 <code>19999</code> 以便從任何遠程系統訪問 NetData 的 web 界面。</p><h4 id="在-ubuntu-debian-中" tabindex="-1">在 Ubuntu/Debian 中 <a class="header-anchor" href="#在-ubuntu-debian-中" aria-label="Permalink to “在 Ubuntu/Debian 中”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw allow 19999</span></span></code></pre></div><h4 id="在-centos-rhel-fedora-中" tabindex="-1">在 CentOS/RHEL/Fedora 中 <a class="header-anchor" href="#在-centos-rhel-fedora-中" aria-label="Permalink to “在 CentOS/RHEL/Fedora 中”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --permanent --add-port=19999/tcp</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><h3 id="啓動-停止-netdata" tabindex="-1">啓動/停止 NetData <a class="header-anchor" href="#啓動-停止-netdata" aria-label="Permalink to “啓動/停止 NetData”">​</a></h3><p>要在使用 Systemd 的系統上啓用和啓動 Netdata 服務，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable netdata</span></span>
<span class="line"><span>$ sudo systemctl start netdata</span></span></code></pre></div><p>要停止：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl stop netdata</span></span></code></pre></div><p>要在使用 Init 的系統上啓用和啓動 Netdata 服務，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo service netdata start</span></span>
<span class="line"><span>$ sudo chkconfig netdata on</span></span></code></pre></div><p>要停止：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo service netdata stop</span></span></code></pre></div><h3 id="通過-web-瀏覽器訪問-netdata" tabindex="-1">通過 Web 瀏覽器訪問 NetData <a class="header-anchor" href="#通過-web-瀏覽器訪問-netdata" aria-label="Permalink to “通過 Web 瀏覽器訪問 NetData”">​</a></h3><p>打開 Web 瀏覽器，然後打開 <code>http://127.0.0.1:19999</code> 或者 <code>http://localhost:19999/</code> 或者 <code>http://ip-address:19999</code>。你應該看到如下頁面。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/06/Netdata-dashboard.png" alt=""></p><p><em>Netdata 儀表板</em></p><p>在儀表板中，你可以找到 Linux 系統的完整統計信息。向下滾動以查看每個部分。</p><p>你可以隨時打開 <code>http://localhost:19999/netdata.conf</code> 來下載和/或查看 NetData 默認配置文件。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/06/Netdata-config-file.png" alt=""></p><p><em>Netdata 配置文件</em></p><h3 id="更新-netdata" tabindex="-1">更新 NetData <a class="header-anchor" href="#更新-netdata" aria-label="Permalink to “更新 NetData”">​</a></h3><p>在 Arch Linux 中，只需運行以下命令即可更新 NetData。如果倉庫中提供了更新版本，那麼就會自動安裝該版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -Syyu</span></span></code></pre></div><p>在基於 DEB 或 RPM 的系統中，只需進入已克隆它的目錄（此例中是 <code>netdata</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd netdata</span></span></code></pre></div><p>拉取最新更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git pull</span></span></code></pre></div><p>然後，使用命令重新構建並更新它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ./netdata-installer.sh</span></span></code></pre></div><h3 id="卸載-netdata" tabindex="-1">卸載 NetData <a class="header-anchor" href="#卸載-netdata" aria-label="Permalink to “卸載 NetData”">​</a></h3><p>進入克隆 NetData 的文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd netdata</span></span></code></pre></div><p>然後，使用命令卸載它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ./netdata-uninstaller.sh --force</span></span></code></pre></div><p>在 Arch Linux 中，使用以下命令卸載它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -Rns netdata</span></span></code></pre></div><h3 id="資源" tabindex="-1">資源 <a class="header-anchor" href="#資源" aria-label="Permalink to “資源”">​</a></h3>`,40)),i("ul",null,[i("li",null,[e(n,{href:"http://netdata.firehol.org/"},{default:t(()=>[...a[6]||(a[6]=[s("NetData 網站",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://github.com/firehol/netdata"},{default:t(()=>[...a[7]||(a[7]=[s("NetData 的 GitHub 頁面",-1)])]),_:1})])]),a[26]||(a[26]=i("hr",null,null,-1)),i("p",null,[a[9]||(a[9]=s("via: ",-1)),e(n,{href:"https://www.ostechnix.com/netdata-real-time-performance-monitoring-tool-linux/"},{default:t(()=>[...a[8]||(a[8]=[s("https://www.ostechnix.com/netdata-real-time-performance-monitoring-tool-linux/",-1)])]),_:1})]),i("p",null,[a[14]||(a[14]=s("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...a[10]||(a[10]=[s("sk",-1)])]),_:1}),a[15]||(a[15]=s(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[11]||(a[11]=[s("lujun9972",-1)])]),_:1}),a[16]||(a[16]=s(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...a[12]||(a[12]=[s("geekpi",-1)])]),_:1}),a[17]||(a[17]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...a[13]||(a[13]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[20]||(a[20]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[18]||(a[18]=[s("LCTT",-1)])]),_:1}),a[21]||(a[21]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...a[19]||(a[19]=[s("Linux中國",-1)])]),_:1}),a[22]||(a[22]=s(" 榮譽推出",-1))])])}const v=p(h,[["render",c]]);export{x as __pageData,v as default};
